import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
 const Logout = () => {
    const navigate = useNavigate;
    useEffect( () =>{
        localStorage.setItem('user' , "" )
        navigate('/login')
    }, [navigate]);
 }
 export default Logout;
